module analog_mux_threshold (vin1, vin2, vsel, vout);

input vin1, vin2, vsel;
output vout;
electrical vin1, vin2, vsel, vout;

parameter real vth = 0.45;

integer selector;
real vout_val;

analog begin
    selector = (V(vsel) > vth) ? 1 : 0;

    @(cross(V(vsel) - vth, +1))
        selector = selector + 1;
    @(cross(V(vsel) - vth, -1))
        selector = 0;

    if (selector == 1)
        vout_val = V(vin1);
    else
        vout_val = V(vin2);

    V(vout) <+ vout_val;
end

endmodule

